/**
 * My Component - Main rendering function
 * Renders text content with optional variant styling
 */

import { componentAttrs } from "../_utils/component.helper";

export default {
  main: async (input = {}) => {
    const { text = 'Hello World!', variant = 'default' } = input;
    const rootClass = variant && variant !== 'default' ? ` class="my-component--${variant}"` : '';

    return /*html*/`
      <div ${componentAttrs("my-component", input)}${rootClass}>
        <div class="my-component__text">
          ${text}
        </div>
      </div>
    `;
  }
}
